    private const string AllocationSql = "CREATE TRIGGER [dbo].[TR_OrderLegalEntityAllocations_StorefrontSource] ON [dbo].[OrderLegalEntityAllocations] AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted a JOIN OrderLines l ON l.StoreId=a.StoreId AND l.OrderId=a.OrderId AND l.Id=a.OrderLineId WHERE l.StorefrontOrderLineId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontLineSources s JOIN StorefrontFulfillmentSources f ON f.StoreId=s.StoreId AND f.Id=s.FulfillmentSourceId JOIN DeliveryOrderLines d ON d.StoreId=f.StoreId AND d.DeliveryOrderId=f.DeliveryOrderId AND d.StorefrontOrderLineId=s.OrderLineId JOIN InventoryTransactions t ON t.StoreId=s.StoreId AND t.Id=s.InventoryTransactionId WHERE s.StoreId=a.StoreId AND s.StorefrontOrderId=l.StorefrontOrderId AND s.OrderLineId=l.StorefrontOrderLineId AND s.InventoryTransactionId=a.InventoryTransactionId AND f.SourceWarehouseId=a.WarehouseId AND f.SourceLegalEntityId=a.LegalEntityId AND a.ProductVariantId=l.VariantId AND a.BaseQuantity=s.BaseQuantity AND t.ReferenceType=11 AND t.TransactionType=80 AND t.PostingPrecisionPolicy=2 AND t.QuantityChange=-a.BaseQuantity AND a.NetAmount=d.Net AND a.LineTotal-a.StorefrontHeaderDiscountAllocated=a.NetAmount AND ((a.InvoiceUnitKind=0 AND a.InvoiceUnitId=l.SellingUnitId AND a.Quantity*l.Multiplier=a.BaseQuantity) OR (a.InvoiceUnitKind=1 AND a.InvoiceUnitId=l.BaseUnitId AND a.Quantity=a.BaseQuantity AND a.ProductUnitConversionId IS NULL)))) THROW 51200,'Native allocation and invoice units must identify actual sealed source quantity and typed dispatch.',1; IF EXISTS(SELECT 1 FROM inserted a JOIN OrderLines l ON l.StoreId=a.StoreId AND l.Id=a.OrderLineId WHERE a.InvoiceUnitKind NOT IN(0,1) OR a.InvoiceUnitKind=1 AND l.StorefrontOrderLineId IS NULL) THROW 51200,'Native base-unit invoicing requires a real native source.',1; IF EXISTS(SELECT 1 FROM deleted d JOIN OrderLines l ON l.StoreId=d.StoreId AND l.Id=d.OrderLineId WHERE l.StorefrontOrderLineId IS NOT NULL) THROW 51200,'Native owner/source allocations are immutable.',1; END;";
    private const string CodBankPredicate = "NOT EXISTS(SELECT 1 FROM BankVerifiedReceipts r JOIN StorefrontOrders o ON o.StoreId=r.OriginStoreId WHERE r.Id=i.GlobalBankReceiptId AND r.OriginStoreId=i.StoreId AND o.Id=i.StorefrontOrderId AND o.PaymentMethod=0 AND o.Phase=4 AND r.Channel=0 AND r.Status IN(N'PAID',N'SUCCESS',N'COMPLETED',N'APPROVED') AND r.AssetConfidence=1 AND r.RoutingProvenance=1 AND r.TimePrecision IN(1,2) AND r.OccurredAtUtc IS NOT NULL AND r.ReviewCode=N'UNMATCHED_CHANNEL_BINDING' AND r.NativeCollectionAuthorityProofJson IS NOT NULL AND DATALENGTH(r.AccountVersion)=24) OR EXISTS(SELECT 1 FROM BankReceiptConsumptions c WHERE c.BankVerifiedReceiptId=i.GlobalBankReceiptId) OR EXISTS(SELECT 1 FROM BankReceiptConflicts c WHERE c.BankVerifiedReceiptId=i.GlobalBankReceiptId) OR EXISTS(SELECT 1 FROM BankPaymentReferences k JOIN BankVerifiedReceipts r ON r.Provider=k.Provider AND r.AccountIdentity=k.AccountIdentity AND r.ProviderReference=k.Reference WHERE r.Id=i.GlobalBankReceiptId)";
    private const string CodReceiptPredicate = "NOT EXISTS(SELECT 1 FROM StorefrontOrders o WHERE o.StoreId=i.StoreId AND o.Id=i.StorefrontOrderId AND o.PaymentMethod=0 AND o.Phase=4) OR i.GlobalBankReceiptId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontCodBankRoutings q JOIN BankVerifiedReceipts r ON r.Id=q.GlobalBankReceiptId AND r.OriginStoreId=q.StoreId WHERE q.StoreId=i.StoreId AND q.StorefrontOrderId=i.StorefrontOrderId AND q.Id=i.CodBankRoutingId AND q.GlobalBankReceiptId=i.GlobalBankReceiptId AND r.Amount=i.Amount AND r.AssetConfidence=1 AND r.RoutingProvenance=1 AND r.ReviewCode=N'UNMATCHED_CHANNEL_BINDING' AND NOT EXISTS(SELECT 1 FROM BankReceiptConflicts c WHERE c.BankVerifiedReceiptId=r.Id)) OR i.POSShiftCashTransactionId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM POSShiftCashTransactions c WHERE c.StoreId=i.StoreId AND c.Id=i.POSShiftCashTransactionId AND c.Type=1 AND c.Amount=i.Amount AND c.IsDeleted=0 AND c.CustomerDebtReceiptId IS NULL AND c.CustomerDepositEntryId IS NULL) OR EXISTS(SELECT 1 FROM TreasuryEntries t WHERE t.StoreId=i.StoreId AND t.POSShiftCashTransactionId=i.POSShiftCashTransactionId AND (t.TargetFund IS NOT NULL OR t.ReversedAtUtc IS NOT NULL OR t.ReversalOfId IS NOT NULL OR t.Fund<>N'cash' OR t.Amount<>i.Amount OR t.OperatingExpenseId IS NOT NULL OR t.PurchasePayableId IS NOT NULL OR t.IsDeleted=1)) OR i.TreasuryEntryId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM TreasuryEntries t WHERE t.StoreId=i.StoreId AND t.Id=i.TreasuryEntryId AND t.POSShiftCashTransactionId=i.POSShiftCashTransactionId AND t.IsVoucherLink=1 AND t.TargetFund IS NULL AND t.ReversedAtUtc IS NULL AND t.ReversalOfId IS NULL AND t.Amount=i.Amount) OR (SELECT ISNULL(SUM(r.Amount),0) FROM StorefrontCodReceipts r WHERE r.StoreId=i.StoreId AND r.StorefrontOrderId=i.StorefrontOrderId)+(SELECT ISNULL(SUM(w.Amount),0) FROM StorefrontCarrierWithholdings w WHERE w.StoreId=i.StoreId AND w.StorefrontOrderId=i.StorefrontOrderId)>(SELECT TotalDue FROM StorefrontOrders WHERE StoreId=i.StoreId AND Id=i.StorefrontOrderId)";
    private const string FundingPredicate = "NOT EXISTS(SELECT 1 FROM StorefrontServiceRevenues r WHERE r.StoreId=i.StoreId AND r.StorefrontOrderId=i.StorefrontOrderId AND r.Id=i.ServiceRevenueId AND (SELECT SUM(f.Amount) FROM StorefrontServiceFundings f WHERE f.StoreId=r.StoreId AND f.ServiceRevenueId=r.Id)<=r.GrossAmount) OR i.CodReceiptId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontCodReceipts r WHERE r.StoreId=i.StoreId AND r.StorefrontOrderId=i.StorefrontOrderId AND r.Id=i.CodReceiptId AND (SELECT ISNULL(SUM(f.Amount),0) FROM StorefrontServiceFundings f WHERE f.CodReceiptId=r.Id)+(SELECT ISNULL(SUM(p.Amount),0) FROM OrderPayments p WHERE p.StorefrontCodReceiptId=r.Id AND p.IsDeleted=0)<=r.Amount) OR i.GlobalBankReceiptId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM BankVerifiedReceipts r JOIN BankReceiptConsumptions c ON c.BankVerifiedReceiptId=r.Id JOIN StorefrontPaymentAllocations a ON a.StoreId=c.OriginStoreId AND a.Id=c.StorefrontAllocationId WHERE r.Id=i.GlobalBankReceiptId AND r.OriginStoreId=i.StoreId AND a.StorefrontOrderId=i.StorefrontOrderId AND c.Channel=2 AND r.AssetConfidence=1 AND r.NeedsReview=0 AND (SELECT ISNULL(SUM(f.Amount),0) FROM StorefrontServiceFundings f WHERE f.GlobalBankReceiptId=r.Id)+(SELECT ISNULL(SUM(p.Amount),0) FROM OrderPayments p WHERE p.BankVerifiedReceiptId=r.Id AND p.IsDeleted=0)<=r.Amount) OR i.CarrierWithholdingId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontCarrierWithholdings w JOIN StorefrontServiceRevenues r ON r.StoreId=w.StoreId AND r.StorefrontOrderId=w.StorefrontOrderId AND r.LegalEntityId=w.LegalEntityId WHERE w.StoreId=i.StoreId AND w.StorefrontOrderId=i.StorefrontOrderId AND w.Id=i.CarrierWithholdingId AND r.Id=i.ServiceRevenueId AND (SELECT ISNULL(SUM(f.Amount),0) FROM StorefrontServiceFundings f WHERE f.CarrierWithholdingId=w.Id)+(SELECT ISNULL(SUM(p.Amount),0) FROM OrderPayments p WHERE p.StorefrontCarrierWithholdingId=w.Id AND p.IsDeleted=0)<=w.Amount)";
    // Further source-specific facts share the same append-only evidence; mutable workflow fields are excluded.
    private static IReadOnlyList<(string Table,string Name,string Sql)> AdditionalTriggers => [
        ("StorefrontOrders","TR_StorefrontOrders_NativeMode",Seal("StorefrontOrders","TR_StorefrontOrders_NativeMode",["Id","StoreId","UseMultiLegalEntitySnapshot","LegalEntityModeCapturedAtUtc"])),
