        ("StorefrontCustodyIncidents","TR_StorefrontCustodyIncidents_Identity",Seal("StorefrontCustodyIncidents","TR_StorefrontCustodyIncidents_Identity",["Id","StoreId","StorefrontOrderId","EvidenceId","ActualCustodySourceIdsJson"])),
        ("POSShiftCashTransactions","TR_POSShiftCashTransactions_StorefrontClaim",CashClaimSql),
        ("TreasuryEntries","TR_TreasuryEntries_StorefrontClaim",TreasuryClaimSql),
        ("OperatingExpenses","TR_OperatingExpenses_StorefrontClaim",ExpenseClaimSql),
        ("BankReceiptConsumptions","TR_BankReceiptConsumptions_CodClaim", "CREATE TRIGGER [dbo].[TR_BankReceiptConsumptions_CodClaim] ON [dbo].[BankReceiptConsumptions] AFTER INSERT AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i JOIN StorefrontCodBankRoutings c ON c.GlobalBankReceiptId=i.BankVerifiedReceiptId) THROW 51200,'A native COD bank source cannot be consumed by POS or QR.',1; END;"),
        ("OrderLines","TR_OrderLines_StorefrontSource",OrderLineSql),
        ("DeliveryOrders","TR_DeliveryOrders_StorefrontSource",DeliverySourceSql),
        ("DeliveryOrderLines","TR_DeliveryOrderLines_StorefrontSource",DeliveryLineSql),
        ("DeliveryPickingWorks","TR_DeliveryPickingWorks_NativeSource","CREATE TRIGGER [dbo].[TR_DeliveryPickingWorks_NativeSource] ON [dbo].[DeliveryPickingWorks] AFTER INSERT,UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i JOIN DeliveryOrders d ON d.StoreId=i.StoreId AND d.Id=i.DeliveryOrderId WHERE i.ApprovedTotal=0 AND (d.SourceKind<>1 OR d.QuotedTotal<>0) OR d.SourceKind=1 AND i.ApprovedTotal IS NOT NULL AND i.ApprovedTotal<>d.QuotedTotal) THROW 51200,'Zero picking value is only valid for a genuine native zero-net source.',1; END;"),
        ("OrderPayments","TR_OrderPayments_StorefrontSource",NativePaymentSourceSql),
