    private static string CashClaimSql => Seal("POSShiftCashTransactions","TR_POSShiftCashTransactions_StorefrontClaim",["Id","StoreId","POSShiftId","Type","Amount","CustomerDebtReceiptId","CustomerDepositEntryId","IsDeleted"],"EXISTS(SELECT 1 FROM StorefrontCodReceipts c WHERE c.StoreId=$.StoreId AND c.POSShiftCashTransactionId=$.Id)");
    private static string NativePaymentSourceSql
    {
        get
        {
            string[] identity = ["Id","StoreId","OrderId","Method","Amount","IsDebtCollection","IsDeleted","PaidAtUtc","BankVerifiedReceiptId","StorefrontCodReceiptId","StorefrontCarrierWithholdingId","Provider","ReferenceCode","MetadataJson","CreatedBy","CreatedAtUtc"];
            return PaymentOwnerSql.Replace(" END;", $$"""
 IF EXISTS(SELECT {{Cols("d", identity)}} FROM deleted d WHERE EXISTS(SELECT 1 FROM StorefrontSaleBindings b WHERE b.StoreId=d.StoreId AND b.SaleOrderId=d.OrderId)
   EXCEPT SELECT {{Cols("i", identity)}} FROM inserted i WHERE EXISTS(SELECT 1 FROM StorefrontSaleBindings b WHERE b.StoreId=i.StoreId AND b.SaleOrderId=i.OrderId))
 THROW 51200,'Native payment source, amount and financial identity are immutable.',1;
 IF EXISTS(SELECT 1 FROM inserted p JOIN StorefrontSaleBindings b ON b.StoreId=p.StoreId AND b.SaleOrderId=p.OrderId
   JOIN Orders o ON o.StoreId=b.StoreId AND o.Id=b.SaleOrderId LEFT JOIN deleted d ON d.Id=p.Id
   WHERE d.Id IS NULL AND o.Status=2)
 THROW 51200,'A completed native sale cannot receive another payment mirror.',1;
 IF EXISTS(SELECT 1 FROM inserted p JOIN StorefrontSaleBindings b ON b.StoreId=p.StoreId AND b.SaleOrderId=p.OrderId
   JOIN StorefrontOrders w ON w.StoreId=b.StoreId AND w.Id=b.StorefrontOrderId
   WHERE p.Amount<=0 OR p.Amount<>ROUND(p.Amount,0) OR p.IsDeleted<>0 OR p.IsDebtCollection<>0 OR NOT(
    (w.PaymentMethod=1 AND p.BankVerifiedReceiptId IS NOT NULL AND p.StorefrontCodReceiptId IS NULL AND p.StorefrontCarrierWithholdingId IS NULL AND p.Method=1 AND EXISTS(
      SELECT 1 FROM BankVerifiedReceipts r JOIN BankReceiptConsumptions c ON c.BankVerifiedReceiptId=r.Id
       JOIN StorefrontPaymentAllocations a ON a.StoreId=c.OriginStoreId AND a.Id=c.StorefrontAllocationId
      WHERE r.Id=p.BankVerifiedReceiptId AND r.OriginStoreId=p.StoreId AND r.IsDeleted=0 AND r.Channel=2 AND r.AssetConfidence=1 AND r.NeedsReview=0 AND r.TimePrecision IN(1,2)
       AND c.Channel=2 AND c.IsDeleted=0 AND c.OriginStoreId=p.StoreId AND a.IsDeleted=0 AND a.StorefrontOrderId=w.Id AND a.Amount=w.TotalDue
       AND NOT EXISTS(SELECT 1 FROM BankReceiptConflicts f WHERE f.BankVerifiedReceiptId=r.Id)))
    OR (w.PaymentMethod=0 AND p.BankVerifiedReceiptId IS NULL AND p.StorefrontCodReceiptId IS NOT NULL AND p.StorefrontCarrierWithholdingId IS NULL AND EXISTS(
      SELECT 1 FROM StorefrontCodReceipts c WHERE c.StoreId=p.StoreId AND c.StorefrontOrderId=w.Id AND c.Id=p.StorefrontCodReceiptId AND c.IsDeleted=0
       AND ((p.Method=0 AND c.POSShiftCashTransactionId IS NOT NULL AND c.GlobalBankReceiptId IS NULL AND c.CodBankRoutingId IS NULL)
         OR (p.Method=1 AND c.POSShiftCashTransactionId IS NULL AND c.GlobalBankReceiptId IS NOT NULL AND c.CodBankRoutingId IS NOT NULL AND EXISTS(
          SELECT 1 FROM StorefrontCodBankRoutings q JOIN BankVerifiedReceipts r ON r.OriginStoreId=q.StoreId AND r.Id=q.GlobalBankReceiptId
          WHERE q.StoreId=c.StoreId AND q.IsDeleted=0 AND q.StorefrontOrderId=c.StorefrontOrderId AND q.Id=c.CodBankRoutingId AND q.GlobalBankReceiptId=c.GlobalBankReceiptId
           AND r.IsDeleted=0 AND r.Channel=0 AND r.AssetConfidence=1 AND r.RoutingProvenance=1 AND r.TimePrecision IN(1,2) AND r.ReviewCode=N'UNMATCHED_CHANNEL_BINDING'
           AND NOT EXISTS(SELECT 1 FROM BankReceiptConflicts f WHERE f.BankVerifiedReceiptId=r.Id)
           AND NOT EXISTS(SELECT 1 FROM BankReceiptConsumptions x WHERE x.BankVerifiedReceiptId=r.Id))))))
    OR (w.PaymentMethod=0 AND p.BankVerifiedReceiptId IS NULL AND p.StorefrontCodReceiptId IS NULL AND p.StorefrontCarrierWithholdingId IS NOT NULL AND p.Method=99 AND EXISTS(
      SELECT 1 FROM StorefrontCarrierWithholdings c WHERE c.StoreId=p.StoreId AND c.IsDeleted=0 AND c.StorefrontOrderId=w.Id AND c.Id=p.StorefrontCarrierWithholdingId))
   ))
 THROW 51200,'Every native sale payment requires its exact supported QR, COD receipt or carrier-withholding source.',1;
 IF EXISTS(SELECT 1 FROM inserted p JOIN StorefrontSaleBindings b ON b.StoreId=p.StoreId AND b.SaleOrderId=p.OrderId JOIN Orders o ON o.StoreId=b.StoreId AND o.Id=b.SaleOrderId
   WHERE (SELECT ISNULL(SUM(x.Amount),0) FROM OrderPayments x WHERE x.StoreId=o.StoreId AND x.OrderId=o.Id AND x.IsDeleted=0)>o.GrandTotal)
 THROW 51200,'Native goods payment mirrors cannot exceed the actual goods sale budget.',1;
 END;
""", StringComparison.Ordinal)
                .Replace("StorefrontSaleBindings b ON", "StorefrontSaleBindings b WITH(HOLDLOCK) ON", StringComparison.Ordinal)
                .Replace("StorefrontSaleBindings b WHERE", "StorefrontSaleBindings b WITH(HOLDLOCK) WHERE", StringComparison.Ordinal);
        }
    }
    private static string PaymentOwnerSql => PaymentSql.Replace(" END;", " IF EXISTS(SELECT 1 FROM inserted p JOIN StorefrontCarrierWithholdings w ON w.StoreId=p.StoreId AND w.Id=p.StorefrontCarrierWithholdingId WHERE (SELECT ISNULL(SUM(x.Amount),0) FROM OrderPayments x JOIN StorefrontCarrierWithholdings c ON c.StoreId=x.StoreId AND c.Id=x.StorefrontCarrierWithholdingId WHERE x.StoreId=p.StoreId AND x.OrderId=p.OrderId AND x.IsDeleted=0 AND c.LegalEntityId=w.LegalEntityId)>(SELECT ISNULL(SUM(a.NetAmount),0) FROM OrderLegalEntityAllocations a WHERE a.StoreId=p.StoreId AND a.OrderId=p.OrderId AND a.LegalEntityId=w.LegalEntityId AND a.IsDeleted=0)) THROW 51200,'Noncash carrier goods settlement cannot exceed the actual same-owner goods budget.',1; IF EXISTS(SELECT 1 FROM inserted p WHERE p.BankVerifiedReceiptId IS NOT NULL AND (SELECT ISNULL(SUM(x.Amount),0) FROM OrderPayments x WHERE x.BankVerifiedReceiptId=p.BankVerifiedReceiptId AND x.IsDeleted=0)+(SELECT ISNULL(SUM(x.Amount),0) FROM StorefrontServiceFundings x WHERE x.GlobalBankReceiptId=p.BankVerifiedReceiptId)>(SELECT Amount FROM BankVerifiedReceipts WHERE Id=p.BankVerifiedReceiptId)) THROW 51200,'Goods and service mirrors share the one actual bank receipt budget.',1; END;",StringComparison.Ordinal);
    private static string CompletedSourceSql => PhaseSql.Replace(" END;", " IF EXISTS(SELECT 1 FROM inserted i JOIN StorefrontSaleBindings b ON b.StoreId=i.StoreId AND b.StorefrontOrderId=i.Id WHERE i.Phase=5 AND ((SELECT ISNULL(SUM(p.Amount),0) FROM OrderPayments p WHERE p.StoreId=b.StoreId AND p.OrderId=b.SaleOrderId AND p.IsDeleted=0 AND p.IsDebtCollection=0)<>i.GoodsAmount OR (SELECT ISNULL(SUM(s.GoodsAmount),0) FROM StorefrontSettlementLinks s WHERE s.StoreId=i.StoreId AND s.StorefrontOrderId=i.Id)<>i.GoodsAmount OR i.ShippingCharge>0 AND NOT EXISTS(SELECT 1 FROM StorefrontServiceRevenues r WHERE r.StoreId=i.StoreId AND r.StorefrontOrderId=i.Id AND r.GrossAmount=i.ShippingCharge AND (SELECT ISNULL(SUM(f.Amount),0) FROM StorefrontServiceFundings f WHERE f.StoreId=r.StoreId AND f.ServiceRevenueId=r.Id)=r.GrossAmount AND r.CashOnlyFunding=CASE WHEN EXISTS(SELECT 1 FROM StorefrontServiceFundings f LEFT JOIN StorefrontCodReceipts c ON c.StoreId=f.StoreId AND c.Id=f.CodReceiptId WHERE f.StoreId=r.StoreId AND f.ServiceRevenueId=r.Id AND (f.GlobalBankReceiptId IS NOT NULL OR f.CarrierWithholdingId IS NOT NULL OR c.GlobalBankReceiptId IS NOT NULL)) THEN 0 ELSE 1 END))) THROW 51200,'Completed native sale must conserve the exact goods, service and actual funding-source budgets.',1; END;",StringComparison.Ordinal);
    private static string NativeBankSourceSql => Seal("BankVerifiedReceipts","TR_BankVerifiedReceipts_CodSource",["Id","OriginStoreId","RoutingProvenance","AccountVersion","NativeCollectionAuthorityProofJson"])
        .Replace(" END;", " UPDATE o SET PaymentState=3,Revision=Revision+1 FROM StorefrontOrders o JOIN StorefrontCodBankRoutings c ON c.StoreId=o.StoreId AND c.StorefrontOrderId=o.Id JOIN inserted i ON i.Id=c.GlobalBankReceiptId AND i.OriginStoreId=c.StoreId WHERE o.PaymentState<>3 AND (i.AssetConfidence<>1 OR i.RoutingProvenance<>1 OR i.TimePrecision=0 OR i.ReviewCode IS NULL OR i.ReviewCode<>N'UNMATCHED_CHANNEL_BINDING' OR EXISTS(SELECT 1 FROM BankReceiptConflicts f WHERE f.BankVerifiedReceiptId=i.Id)); END;",StringComparison.Ordinal);
    private const string TreasuryClaimSql = "CREATE TRIGGER [dbo].[TR_TreasuryEntries_StorefrontClaim] ON [dbo].[TreasuryEntries] AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i JOIN StorefrontCodReceipts c ON c.StoreId=i.StoreId AND c.POSShiftCashTransactionId=i.POSShiftCashTransactionId WHERE i.IsDeleted<>0 OR i.TargetFund IS NOT NULL OR i.Fund<>N'cash' OR i.Amount<>c.Amount OR i.IsVoucherLink<>1 OR i.ReversalOfId IS NOT NULL OR i.ReversedAtUtc IS NOT NULL OR i.OperatingExpenseId IS NOT NULL OR i.PurchasePayableId IS NOT NULL) OR EXISTS(SELECT 1 FROM deleted d JOIN StorefrontCodReceipts c ON c.StoreId=d.StoreId AND (c.TreasuryEntryId=d.Id OR c.POSShiftCashTransactionId=d.POSShiftCashTransactionId) LEFT JOIN inserted i ON i.Id=d.Id WHERE i.Id IS NULL OR i.StoreId<>d.StoreId OR i.Amount<>d.Amount OR i.POSShiftCashTransactionId IS NULL OR i.POSShiftCashTransactionId<>d.POSShiftCashTransactionId OR i.ReversedAtUtc IS NOT NULL OR i.IsDeleted=1) OR EXISTS(SELECT 1 FROM inserted i JOIN StorefrontCarrierWithholdings w ON w.StoreId=i.StoreId AND w.OperatingExpenseId=i.OperatingExpenseId) THROW 51200,'Claimed external COD cash and noncash carrier deductions cannot be transferred, reversed or paid twice.',1; END;";
    private static string ExpenseClaimSql => Seal("OperatingExpenses","TR_OperatingExpenses_StorefrontClaim",["Id","StoreId","Name","Amount","Category","RecognitionFrom","RecognitionTo","Status","IsDeleted"],"EXISTS(SELECT 1 FROM StorefrontCarrierWithholdings c WHERE c.StoreId=$.StoreId AND c.OperatingExpenseId=$.Id)").Replace(" END;", " IF EXISTS(SELECT 1 FROM inserted i JOIN StorefrontCarrierWithholdings c ON c.StoreId=i.StoreId AND c.OperatingExpenseId=i.Id WHERE i.IsPaid<>1 OR i.PaymentMethod<>N'carrier-withholding' OR i.Amount<>c.Amount) THROW 51200,'Carrier withholding retains its actual noncash settlement source.',1; END;",StringComparison.Ordinal);
    private const string OrderLineSql = "CREATE TRIGGER [dbo].[TR_OrderLines_StorefrontSource] ON [dbo].[OrderLines] AFTER INSERT,UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE i.StorefrontOrderLineId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontOrderLines w JOIN StorefrontOrders p ON p.StoreId=w.StoreId AND p.Id=w.StorefrontOrderId WHERE w.StoreId=i.StoreId AND w.Id=i.StorefrontOrderLineId AND w.StorefrontOrderId=i.StorefrontOrderId AND i.VariantId=w.VariantId AND i.Quantity=w.Quantity AND i.Multiplier=w.BaseMultiplier AND i.UnitPrice=w.UnitPrice AND i.StorefrontRoundingAdjustment=w.RoundingAdjustment AND i.IsPromotionGift=w.IsGift)) THROW 51200,'Native goods lines retain exact accepted selling-unit and gift facts.',1; END;";
    private const string DeliverySourceSql = "CREATE TRIGGER [dbo].[TR_DeliveryOrders_StorefrontSource] ON [dbo].[DeliveryOrders] AFTER INSERT,UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE i.SourceKind=1 AND NOT EXISTS(SELECT 1 FROM StorefrontFulfillmentSources s JOIN StorefrontOrders o ON o.StoreId=s.StoreId AND o.Id=s.StorefrontOrderId WHERE s.StoreId=i.StoreId AND s.Id=i.StorefrontFulfillmentSourceId AND s.StorefrontOrderId=i.StorefrontOrderId AND s.SourceWarehouseId=i.SourceWarehouseId AND s.SourceLegalEntityId=i.SourceLegalEntityId AND i.StorefrontAllowNegativeInventory=CASE WHEN JSON_VALUE(o.AddressSnapshotJson,'$.allowNegative')=N'true' THEN 1 ELSE 0 END)) THROW 51200,'Native delivery must use its actual sealed source and inventory policy.',1; END;";
    private const string DeliveryLineSql = "CREATE TRIGGER [dbo].[TR_DeliveryOrderLines_StorefrontSource] ON [dbo].[DeliveryOrderLines] AFTER INSERT AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i JOIN DeliveryOrders d ON d.StoreId=i.StoreId AND d.Id=i.DeliveryOrderId WHERE d.SourceKind=0 AND (i.SourceCartId IS NULL OR i.SourceCartId<>d.SourceCartId OR i.StorefrontOrderId IS NOT NULL OR i.StorefrontOrderLineId IS NOT NULL OR i.StorefrontBaseQuantity IS NOT NULL) OR d.SourceKind=1 AND (i.StorefrontBaseQuantity IS NULL OR i.StorefrontBaseQuantity<=0 OR NOT EXISTS(SELECT 1 FROM StorefrontOrderLines w CROSS APPLY OPENJSON(w.SnapshotJson,'$.allocations')WITH(FulfillmentSourceId int '$.fulfillmentSourceId',BaseQuantity decimal(18,4) '$.baseQuantity')a WHERE w.StoreId=i.StoreId AND w.StorefrontOrderId=d.StorefrontOrderId AND w.Id=i.StorefrontOrderLineId AND i.StorefrontOrderId=w.StorefrontOrderId AND i.VariantId=w.VariantId AND i.OrderedQuantity=w.Quantity AND i.BaseMultiplier=w.BaseMultiplier AND a.FulfillmentSourceId=d.StorefrontFulfillmentSourceId AND a.BaseQuantity=i.StorefrontBaseQuantity))) THROW 51200,'Native picking units must retain exact sealed allocation base quantity.',1; END;";
    private const string PaymentSql = "CREATE TRIGGER [dbo].[TR_OrderPayments_StorefrontSource] ON [dbo].[OrderPayments] AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted p WHERE p.StorefrontCodReceiptId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontCodReceipts c JOIN StorefrontSaleBindings b ON b.StoreId=c.StoreId AND b.StorefrontOrderId=c.StorefrontOrderId WHERE c.StoreId=p.StoreId AND c.Id=p.StorefrontCodReceiptId AND b.SaleOrderId=p.OrderId AND p.IsDeleted=0 AND p.Method=CASE WHEN c.GlobalBankReceiptId IS NULL THEN 0 ELSE 1 END AND (SELECT ISNULL(SUM(x.Amount),0) FROM OrderPayments x WHERE x.StorefrontCodReceiptId=c.Id AND x.IsDeleted=0)+(SELECT ISNULL(SUM(x.Amount),0) FROM StorefrontServiceFundings x WHERE x.CodReceiptId=c.Id)<=c.Amount) OR p.StorefrontCarrierWithholdingId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontCarrierWithholdings c JOIN StorefrontSaleBindings b ON b.StoreId=c.StoreId AND b.StorefrontOrderId=c.StorefrontOrderId WHERE c.StoreId=p.StoreId AND c.Id=p.StorefrontCarrierWithholdingId AND b.SaleOrderId=p.OrderId AND p.IsDeleted=0 AND p.Method=99 AND (SELECT ISNULL(SUM(x.Amount),0) FROM OrderPayments x WHERE x.StorefrontCarrierWithholdingId=c.Id AND x.IsDeleted=0)+(SELECT ISNULL(SUM(x.Amount),0) FROM StorefrontServiceFundings x WHERE x.CarrierWithholdingId=c.Id)<=c.Amount)) THROW 51200,'Native payment mirrors require the actual settled source and shared goods/service budget.',1; IF EXISTS(SELECT 1 FROM deleted d WHERE (d.StorefrontCodReceiptId IS NOT NULL OR d.StorefrontCarrierWithholdingId IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM inserted i WHERE i.Id=d.Id AND i.StoreId=d.StoreId AND i.OrderId=d.OrderId AND i.Amount=d.Amount AND i.Method=d.Method AND ISNULL(i.StorefrontCodReceiptId,0)=ISNULL(d.StorefrontCodReceiptId,0) AND ISNULL(i.StorefrontCarrierWithholdingId,0)=ISNULL(d.StorefrontCarrierWithholdingId,0) AND i.IsDeleted=0)) THROW 51200,'Actual COD receipt mirrors are immutable.',1; END;";
    private const string SettlementSql = "CREATE TRIGGER [dbo].[TR_StorefrontSettlementLinks_NativeSource] ON [dbo].[StorefrontSettlementLinks] AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM deleted) THROW 51200,'Native settlement proof is append-only.',1; IF EXISTS(SELECT 1 FROM inserted i JOIN StorefrontSaleBindings b ON b.StoreId=i.StoreId AND b.StorefrontOrderId=i.StorefrontOrderId AND b.SaleOrderId=i.SaleOrderId JOIN StorefrontFulfillmentSources s ON s.StoreId=i.StoreId AND s.StorefrontOrderId=i.StorefrontOrderId AND s.Id=i.FulfillmentSourceId JOIN DeliveryOrders d ON d.StoreId=s.StoreId AND d.Id=s.DeliveryOrderId WHERE d.SourceKind<>1 OR d.StorefrontOrderId<>i.StorefrontOrderId OR d.StorefrontFulfillmentSourceId<>i.FulfillmentSourceId OR d.QuotedTotal<>i.GoodsAmount OR NOT EXISTS(SELECT 1 FROM DeliveryJournalEntries j WHERE j.StoreId=d.StoreId AND j.DeliveryOrderId=d.Id AND j.Kind=1)) THROW 51200,'Child settlement must identify actual native dispatch and its exact sealed goods value.',1; END;";
    private const string PhaseSql = "CREATE TRIGGER [dbo].[TR_StorefrontOrders_FulfillmentProof] ON [dbo].[StorefrontOrders] AFTER UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE i.Phase IN(3,4,5) AND (NOT EXISTS(SELECT 1 FROM StorefrontFulfillmentWorks w WHERE w.StoreId=i.StoreId AND w.StorefrontOrderId=i.Id) OR EXISTS(SELECT 1 FROM StorefrontFulfillmentSources s WHERE s.StoreId=i.StoreId AND s.StorefrontOrderId=i.Id AND NOT EXISTS(SELECT 1 FROM StorefrontFulfillmentWorks w WHERE w.StoreId=s.StoreId AND w.FulfillmentSourceId=s.Id AND ((i.Phase=3 AND w.Stage IN(2,3,4,5)) OR (i.Phase IN(4,5) AND w.Stage=3)))))) THROW 51200,'Parent shipping and delivery require every real child proof.',1; IF EXISTS(SELECT 1 FROM inserted i WHERE i.Phase=5 AND NOT EXISTS(SELECT 1 FROM StorefrontSaleBindings b JOIN Orders o ON o.StoreId=b.StoreId AND o.Id=b.SaleOrderId WHERE b.StoreId=i.StoreId AND b.StorefrontOrderId=i.Id AND o.GrandTotal=i.GoodsAmount AND o.Status=2 AND o.PaymentStatus=2)) THROW 51200,'Completed website orders require their one actual positive goods sale.',1; END;";
    private const string InvoiceHeadSql = "CREATE TRIGGER [dbo].[TR_InvoiceHeads_StorefrontSource] ON [dbo].[InvoiceHeads] AFTER INSERT,UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE i.StorefrontServiceRevenueId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM StorefrontServiceRevenues r WHERE r.StoreId=i.StoreId AND r.Id=i.StorefrontServiceRevenueId AND i.OrderId IS NULL AND i.LegalEntityId=r.LegalEntityId AND i.NativeServiceRecognizedAtUtc=r.RecognizedAtUtc AND i.NativeServiceInvoiceRoute=r.InvoiceRoute AND i.NativeServiceActorUserId=r.ActorUserId AND i.GrandTotal=r.GrossAmount)) THROW 51200,'Native service invoice must retain its actual owner, gross, route and recognition source.',1; END;";
    private const string InvoiceDetailSql = "CREATE TRIGGER [dbo].[TR_InvoiceDetails_StorefrontSource] ON [dbo].[InvoiceDetails] AFTER INSERT,UPDATE AS BEGIN SET NOCOUNT ON; IF EXISTS(SELECT 1 FROM inserted i WHERE i.SourceType=3 AND i.StorefrontServiceRevenueId IS NULL OR i.StorefrontServiceRevenueId IS NOT NULL AND (i.SourceType<>3 OR i.OrderLineId IS NOT NULL OR i.ProductVariantId IS NOT NULL OR NOT EXISTS(SELECT 1 FROM StorefrontServiceRevenues r JOIN InvoiceHeads h ON h.StoreId=r.StoreId WHERE r.StoreId=i.StoreId AND r.Id=i.StorefrontServiceRevenueId AND h.Id=i.InvoiceHeadId AND h.LegalEntityId=r.LegalEntityId AND (h.StorefrontServiceRevenueId=r.Id OR h.IsAutoInvoiceGroup=1) AND i.Quantity=1 AND i.Amount=r.NetAmount AND i.VatRate=r.TaxRate AND i.VatAmount=r.TaxAmount AND i.TotalAmount=r.GrossAmount))) THROW 51200,'Native invoice service details are real typed sources, never inventory SKUs.',1; END;";
    public static bool TryGetTrigger(string migrationId,SqlOperation operation,out(string Table,DatabaseTriggerSchema Trigger) result)
    {
        result=default; if(migrationId!=MigrationId||operation.SuppressTransaction)return false;
        foreach(var item in Triggers) if(item.Sql==operation.Sql){result=(item.Table,new(DatabaseSchemaNormalization.NormalizeIdentifier(item.Name),DeliverySchemaSqlCatalog.NormalizeDefinition(item.Sql),false,false,true,true));return true;}
        return false;
    }
}













